/* port.h: the ported monsters as the core sees them (module/port.c).
 * port_monsters[] is generated by module/build.py from allocations.toml (IDs) and monsters/<name>/package.toml (C
 * symbol prefix), in registry order. Every registered monster's data file nativeNX/mh4uport/<name>.bin always ships
 * (tables + text, tools/portdata.py); the monster counts as INSTALLED when its assets are present (its monster arc).
 * Gear / items / Notes / name come from the data file whatever is installed (IDs never move); quests, spawning and
 * quest-time hooks need the monster installed. */
#pragma once
#include <stdint.h>
#include "alloc.h"

#define PORT_N ((int)PORT_MONSTER_COUNT)
#define PORT_LANGS 5          /* eng fre ger ita spa: text order in every data section */

struct port_monster {
    const char *name;                     /* data file + log name */
    uint16_t em_id, index, donor_index, standin_id;   /* standin 0 = none */
    uint16_t save_index, save_id, name_entry, notes_entry;
    uint32_t quests[2], quest_slots[2];   /* 0 = none */
    void (*register_class)(void);         /* 0 = a GU class runs it (package.toml gu_class) */
};
extern const struct port_monster port_monsters[];   /* out/port_monsters.c */
extern uint32_t port_manifests[][51];               /* registry file manifests (reg_files[index] points here) */

/* data file: 1 = loaded and valid (loads on the first call, from any thread) */
int port_data(int m);
void port_load_all(void);
/* the nth section with this tag (several may share one), 0 if none; *size = its size */
const uint8_t *port_section(int m, const char *tag, int nth, uint32_t *size);
#define PORT_U32(sec, off) (*(const uint32_t *)((sec) + (off)))
#define PORT_STR(sec, off) ((const char *)(sec) + PORT_U32(sec, off))
/* 1 = its assets are installed (monster arc present) */
int port_installed(int m);

int port_by_em(uint32_t em_id);           /* -1 = none */
int port_by_index(uint32_t index);
/* quests: the accepted / running quest ID (0 = none); the monster owning a quest (and its quest number 0 / 1) */
uint32_t port_quest_id(void);
int port_quest_owner(uint32_t quest_id, int *which);
int port_running_quest(int *which);       /* owner of the current quest if installed, else -1 */

void notes_data_loaded(int m);            /* notes.c: the monster's Notes entry, after its data loaded */
